size_t pqcp_channel_fault_conformance_catalog_count(void)
{
	return ARRAY_SIZE(channel_fault_catalog);
}

int pqcp_channel_fault_conformance_catalog_get(
	size_t index,
	struct pqcp_operation_conformance_case *test_case)
{
	if (index >= ARRAY_SIZE(channel_fault_catalog) ||
	    test_case == NULL) {
		return -EINVAL;
	}
	*test_case = channel_fault_catalog[index];
	test_case->schema_version =
		PQCP_OPERATION_CONFORMANCE_SCHEMA_VERSION;
	test_case->domain = PQCP_OPERATION_CONFORMANCE_CHANNEL_FAULT;
	test_case->case_id =
		PQCP_OPERATION_CONFORMANCE_CASE_ID(
			test_case->domain,
			test_case->condition,
			test_case->operation);
	return 0;
}

int pqcp_channel_fault_conformance_catalog_audit(void)
{
	if (ARRAY_SIZE(channel_fault_catalog) !=
	    PQCP_OPERATION_CONFORMANCE_CASES_PER_DOMAIN) {
		return -EBADMSG;
	}
	for (size_t index = 0U;
	     index < ARRAY_SIZE(channel_fault_catalog);
	     ++index) {
		struct pqcp_operation_conformance_case test_case_value;
		const struct pqcp_operation_conformance_case *test_case =
			&test_case_value;
		struct pqcp_channel_fault_policy_decision actual;
		int ret;

		ret = pqcp_channel_fault_conformance_catalog_get(
			index, &test_case_value);
		if (ret != 0) {
			return ret;
		}
		if (test_case->schema_version !=
			    PQCP_OPERATION_CONFORMANCE_SCHEMA_VERSION ||
		    test_case->domain != PQCP_OPERATION_CONFORMANCE_CHANNEL_FAULT ||
		    test_case->case_id !=
			    PQCP_OPERATION_CONFORMANCE_CASE_ID(
				test_case->domain,
				test_case->condition,
				test_case->operation)) {
			return -EBADMSG;
		}
		ret = pqcp_channel_fault_policy_lookup(
			(enum pqcp_channel_fault_condition)test_case->condition,
			(enum pqcp_channel_control_kind)test_case->operation,
			&actual);
		if (ret != 0) {
			return ret;
		}
		if (
		    actual.directive != test_case->decision ||
		    actual.next_state != test_case->next_state ||
		    actual.maximum_attempts != test_case->parameter0 ||
		    actual.delay_ms != test_case->parameter1 ||
		    actual.reason_mask != test_case->reason_mask ||
		    actual.error != test_case->expected_error) {
			return -EBADMSG;
		}
	}
	return 0;
}
